import { routes } from "@/config/routes";
import { env } from "@/env";

/**
 * Clerk configuration.
 *
 * Read by the provider (`src/config/providers/clerk.provider.tsx`), the proxy
 * (`src/proxy.ts`), the server facade (`src/server/clerk/facade.ts`) and the
 * client hooks (`src/lib/auth/clerk-client.ts`). Only used when
 * `AUTH_STRATEGY=clerk`.
 *
 * Sign-in and sign-up happen on Clerk's hosted Account Portal. The app's own
 * `/sign-in` and `/sign-up` routes stay the addresses everything links to; the
 * proxy bounces them to the portal and Clerk sends the person back to
 * `afterSignInUrl` (or the `next` query parameter) afterwards.
 */

/**
 * Both keys are present. `features-config.ts` derives
 * `NEXT_PUBLIC_FEATURE_AUTH_CLERK_ENABLED` from the same pair.
 */
export function isClerkConfigured(): boolean {
  return !!(env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY && env.CLERK_SECRET_KEY);
}

/**
 * Clerk publishable key for client-side operations
 */
export function getClerkPublishableKey(): string {
  if (!env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY) {
    throw new Error("NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY is not configured");
  }
  return env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY;
}

/**
 * Clerk secret key for server-side operations
 */
export function getClerkSecretKey(): string {
  if (!env.CLERK_SECRET_KEY) {
    throw new Error("CLERK_SECRET_KEY is not configured");
  }
  return env.CLERK_SECRET_KEY;
}

/**
 * Clerk webhook signing secret (dashboard.clerk.com, Webhooks), if set.
 */
export function getClerkWebhookSecret(): string | undefined {
  return env.CLERK_WEBHOOK_SECRET;
}

export const clerkConfig = {
  // Appearance customization to match Shipkit's design
  appearance: {
    elements: {
      formButtonPrimary: "bg-primary text-primary-foreground hover:bg-primary/90",
      formFieldInput: "border border-input bg-background text-foreground",
      card: "bg-card text-card-foreground shadow-lg",
    },
    layout: {
      socialButtonsPlacement: "top" as const,
      showOptionalFields: false,
    },
  },
  /** In-app routes that `src/proxy.ts` forwards to Clerk's hosted pages. */
  signInUrl: routes.auth.signIn,
  signUpUrl: routes.auth.signUp,
  /** Where Clerk sends the person after signing in or up. */
  afterSignInUrl: routes.app.dashboard,
  afterSignUpUrl: routes.app.dashboard,
  /** Where sign-out lands. */
  afterSignOutUrl: routes.home,
  // Clerk dashboard redirect for user management
  userProfileUrl: routes.settings.profile,
} as const;

import type { User } from "@clerk/nextjs/server";
import { auth, currentUser } from "@clerk/nextjs/server";
import { mapClerkSession } from "@/lib/auth/session-mapping";
import { logger } from "@/lib/logger";

/**
 * Server-side helpers on top of Clerk's `auth()` and `currentUser()`.
 *
 * Only used when Clerk is the active authentication strategy. App code should
 * read the session through `auth()` from `@/server/auth`, which dispatches to
 * `src/server/clerk/facade.ts`; these are for code that needs Clerk-specific
 * data (organizations, roles) the app's session shape does not carry.
 */

/**
 * Get the current authenticated user from Clerk
 */
export async function getClerkUser(): Promise<User | null> {
  try {
    return await currentUser();
  } catch (error) {
    logger.error("Clerk: failed to read the current user", error);
    return null;
  }
}

/**
 * Get the current user's session information
 */
export async function getClerkSession() {
  try {
    const { userId, sessionId, orgId } = await auth();
    return {
      userId,
      sessionId,
      orgId,
      isAuthenticated: !!userId,
    };
  } catch (error) {
    logger.error("Clerk: failed to read the session", error);
    return {
      userId: null,
      sessionId: null,
      orgId: null,
      isAuthenticated: false,
    };
  }
}

/**
 * Check if user is authenticated
 */
export async function isClerkAuthenticated(): Promise<boolean> {
  const session = await getClerkSession();
  return session.isAuthenticated;
}

/**
 * Get user ID from Clerk session
 */
export async function getClerkUserId(): Promise<string | null> {
  const session = await getClerkSession();
  return session.userId;
}

/**
 * Convert a Clerk user to the app's `User` shape (the same mapping the
 * session facade uses).
 */
export function formatClerkUser(clerkUser: User) {
  return mapClerkSession(clerkUser, null)?.user ?? null;
}

/**
 * Get formatted user data for the current authenticated user
 */
export async function getCurrentFormattedUser() {
  const clerkUser = await getClerkUser();
  if (!clerkUser) return null;
  return formatClerkUser(clerkUser);
}

/**
 * Check if user has a specific role (for organization-based auth)
 */
export async function hasClerkRole(role: string): Promise<boolean> {
  try {
    const { orgRole } = await auth();
    return orgRole === role;
  } catch (error) {
    logger.error("Clerk: failed to check the organization role", error);
    return false;
  }
}

/**
 * Check if user is an admin (for organization-based auth)
 */
export async function isClerkAdmin(): Promise<boolean> {
  return hasClerkRole("admin");
}

/**
 * Get user's organization information
 */
export async function getClerkOrganization() {
  try {
    const { orgId, orgRole, orgSlug } = await auth();
    return {
      id: orgId,
      role: orgRole,
      slug: orgSlug,
      hasOrganization: !!orgId,
    };
  } catch (error) {
    logger.error("Clerk: failed to read the organization", error);
    return {
      id: null,
      role: null,
      slug: null,
      hasOrganization: false,
    };
  }
}

"use client";

import { useSession as useClerkSessionResource, useUser } from "@clerk/nextjs";
import type { Session } from "next-auth";
import { useCallback, useEffect, useMemo } from "react";
import { SEARCH_PARAM_KEYS } from "@/config/search-param-keys";
import { clerkConfig } from "@/lib/auth/clerk-config";
import { mapClerkSession } from "@/lib/auth/session-mapping";

/**
 * Clerk behind the `@/lib/auth/use-session` hooks.
 *
 * `useClerkSession` maps Clerk's `useUser()` and `useSession()` into the
 * `next-auth/react` `{ data, status, update }` shape, and `clerkSignIn` /
 * `clerkSignOut` give `signIn` / `signOut` their Auth.js semantics. Only
 * `use-session.ts` imports this module, and only calls into it when Clerk is
 * the active strategy, so the hooks below always run inside `ClerkProvider`.
 *
 * Sign-in goes to the app's own sign-in route with `next`; `src/proxy.ts`
 * forwards it to Clerk's hosted Account Portal. Sign-out uses the `Clerk`
 * global that `ClerkProvider` installs, since `useClerk()` is a hook and
 * `signOut` is a plain function.
 */

type SessionStatus = "loading" | "authenticated" | "unauthenticated";

interface UseSessionOptions<R extends boolean> {
  required: R;
  onUnauthenticated?: () => void;
}

interface SignInOptionsLike {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
  [key: string]: unknown;
}

interface SignOutOptionsLike {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
}

/** What `ClerkProvider` puts on `window` once clerk-js has loaded. */
interface ClerkWindow extends Window {
  Clerk?: { signOut: () => Promise<void> };
}

const currentPage = () =>
  typeof window === "undefined" ? clerkConfig.afterSignInUrl : window.location.href;

const navigate = (url: string) => {
  if (typeof window !== "undefined") window.location.href = url;
};

/** Same-origin paths only, so `next` cannot become an open redirect. */
const toReturnPath = (value: string | undefined): string | undefined => {
  if (!value) return undefined;
  if (value.startsWith("/") && !value.startsWith("//")) return value;
  if (typeof window === "undefined") return undefined;
  try {
    const url = new URL(value, window.location.origin);
    return url.origin === window.location.origin ? url.pathname + url.search + url.hash : undefined;
  } catch {
    return undefined;
  }
};

/** The in-app sign-in route carrying `next`, which the proxy forwards to Clerk. */
export function clerkSignInUrl(nextUrl?: string): string {
  const next = toReturnPath(nextUrl);
  if (!next) return clerkConfig.signInUrl;
  const params = new URLSearchParams({ [SEARCH_PARAM_KEYS.nextUrl]: next });
  return `${clerkConfig.signInUrl}?${params.toString()}`;
}

export function useClerkSession<R extends boolean>(options?: UseSessionOptions<R>) {
  const { isLoaded, user } = useUser();
  const { session: clerkSession } = useClerkSessionResource();
  const expireAt = clerkSession?.expireAt ?? null;
  const session = useMemo(() => mapClerkSession(user ?? null, expireAt), [user, expireAt]);
  const status: SessionStatus = !isLoaded
    ? "loading"
    : session
      ? "authenticated"
      : "unauthenticated";

  const update = useCallback(async (): Promise<Session | null> => {
    if (!user) return null;
    await user.reload();
    return mapClerkSession(user, expireAt);
  }, [user, expireAt]);

  const required = options?.required === true;
  const onUnauthenticated = options?.onUnauthenticated;
  useEffect(() => {
    if (!required || status !== "unauthenticated") return;
    if (onUnauthenticated) onUnauthenticated();
    else navigate(clerkSignInUrl(currentPage()));
  }, [required, status, onUnauthenticated]);

  return { data: session, status, update };
}

/**
 * `signIn(provider, options)`: Clerk's hosted page offers every method set up
 * in the dashboard, so `provider` is ignored. `redirect: false` returns the
 * URL instead of navigating.
 */
export async function clerkSignIn(_provider?: string, options?: SignInOptionsLike) {
  const url = clerkSignInUrl(options?.redirectTo ?? options?.callbackUrl ?? currentPage());
  if (options?.redirect !== false) navigate(url);
  return { ok: true, error: undefined, code: undefined, status: 200, url };
}

/**
 * `signOut(options)`: ends the Clerk session, then navigates to
 * `callbackUrl` / `redirectTo` (default home) unless `redirect: false`.
 */
export async function clerkSignOut(options?: SignOutOptionsLike) {
  const url =
    toReturnPath(options?.redirectTo ?? options?.callbackUrl) ?? clerkConfig.afterSignOutUrl;
  if (typeof window !== "undefined") {
    await (window as ClerkWindow).Clerk?.signOut();
  }
  if (options?.redirect !== false) navigate(url);
  return { url };
}

import { auth as clerkAuth, clerkClient, currentUser } from "@clerk/nextjs/server";
import { redirect } from "next/navigation";
import type { Session } from "next-auth";
import { SEARCH_PARAM_KEYS } from "@/config/search-param-keys";
import { clerkConfig } from "@/lib/auth/clerk-config";
import { mapClerkSession } from "@/lib/auth/session-mapping";
import { logger } from "@/lib/logger";

/**
 * Clerk behind the `@/server/auth` facade.
 *
 * Everything in the app reads sessions through `auth()` from `@/server/auth`
 * and expects the Auth.js shape (`{ user, expires }` with the augmented
 * `User`). This module produces that shape from Clerk's `auth()` and
 * `currentUser()` so the rest of the app does not know which strategy is
 * active. Clerk's `auth()` needs `clerkMiddleware()` to have run for the
 * request, which `src/proxy.ts` does whenever Clerk is the active strategy.
 *
 * Sign-in and sign-up use Clerk's hosted Account Portal. `clerkSignIn` sends
 * the person to the app's own sign-in route with a `next` parameter, and the
 * proxy forwards that route to the portal with the same return URL, so every
 * existing link to `/sign-in` behaves the same way. `auth({ protect: true })`
 * in `@/server/auth` redirects to that route too.
 */

/**
 * Current session from Clerk, in the app's shape. `null` when signed out or
 * when Clerk cannot be reached; the caller decides whether that means a
 * redirect.
 */
export async function getClerkSession(): Promise<Session | null> {
  try {
    const { userId, sessionClaims } = await clerkAuth();
    if (!userId) return null;
    const user = await currentUser();
    return mapClerkSession(user, sessionClaims?.exp ?? null);
  } catch (error) {
    logger.error("Clerk: failed to read session", error);
    return null;
  }
}

interface SignInOptions {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
  [key: string]: unknown;
}

const toOptions = (options?: FormData | SignInOptions): SignInOptions =>
  options instanceof FormData ? Object.fromEntries(options) : (options ?? {});

/** Only same-origin paths may be used as a return URL, so `next` cannot be an open redirect. */
const isSafePath = (value: unknown): value is string =>
  typeof value === "string" && value.startsWith("/") && !value.startsWith("//");

/**
 * The in-app sign-in (or sign-up) route carrying `next`. `src/proxy.ts` turns
 * it into Clerk's hosted page with `returnBackUrl` set to the same path.
 */
export function clerkSignInUrl(nextUrl?: string, page: "signIn" | "signUp" = "signIn"): string {
  const base = page === "signUp" ? clerkConfig.signUpUrl : clerkConfig.signInUrl;
  if (!isSafePath(nextUrl)) return base;
  const params = new URLSearchParams({ [SEARCH_PARAM_KEYS.nextUrl]: nextUrl });
  return `${base}?${params.toString()}`;
}

/**
 * `signIn(provider, options)` with Auth.js semantics. Clerk's hosted page
 * offers every method configured in the dashboard, so `provider` is ignored.
 * `redirect: false` returns `{ ok, url }` instead of redirecting.
 */
export async function clerkSignIn(_provider?: string, options?: FormData | SignInOptions) {
  const opts = toOptions(options);
  const redirectTo = opts.redirectTo ?? opts.callbackUrl ?? clerkConfig.afterSignInUrl;
  const url = clerkSignInUrl(redirectTo);
  if (opts.redirect !== false) redirect(url);
  return { ok: true, url };
}

/**
 * `signOut(options)` with Auth.js semantics: revokes the current Clerk
 * session, then redirects unless `redirect: false`. Clerk's middleware sees the
 * revoked session on the next request and treats the browser as signed out.
 */
export async function clerkSignOut(options?: FormData | SignInOptions) {
  const opts = toOptions(options);
  const redirectTo = isSafePath(opts.redirectTo) ? opts.redirectTo : clerkConfig.afterSignOutUrl;
  try {
    const { sessionId } = await clerkAuth();
    if (sessionId) {
      const client = await clerkClient();
      await client.sessions.revokeSession(sessionId);
    }
  } catch (error) {
    // No session to revoke is not a failure for the person signing out.
    logger.warn("Clerk: sign-out reported an error", error);
  }
  if (opts.redirect !== false) redirect(redirectTo);
  return { url: redirectTo };
}

import { clerkMiddleware, createRouteMatcher } from "@clerk/nextjs/server";
import { NextResponse } from "next/server";
import { SEARCH_PARAM_KEYS } from "@/config/search-param-keys";
import { isClerkActive } from "@/lib/auth/auth-strategy";
import { clerkConfig } from "@/lib/auth/clerk-config";

/**
 * Request proxy (Next 16's name for middleware; `middleware.ts` is deprecated).
 *
 * Clerk reads and refreshes its session cookie here, so its server `auth()`
 * works in pages, layouts, route handlers and server actions. The app's own
 * `/sign-in` and `/sign-up` routes are forwarded to Clerk's hosted Account
 * Portal with `next` (if any) as the return URL, and a signed-in visitor to
 * either route is sent on to the dashboard.
 *
 * When Clerk is not the active strategy this is a pass-through: every request
 * gets `NextResponse.next()` and nothing else runs.
 */

const isSignIn = createRouteMatcher([`${clerkConfig.signInUrl}(.*)`]);
const isSignUp = createRouteMatcher([`${clerkConfig.signUpUrl}(.*)`]);

/**
 * Pointing Clerk's own sign-in / sign-up URLs at an in-app route (to embed
 * `<ClerkSignInForm />` there) means that route must render, not forward:
 * forwarding it to itself would loop.
 */
const clerkOwnsSignInRoute = process.env.NEXT_PUBLIC_CLERK_SIGN_IN_URL?.startsWith("/") ?? false;
const clerkOwnsSignUpRoute = process.env.NEXT_PUBLIC_CLERK_SIGN_UP_URL?.startsWith("/") ?? false;

/** Same-origin paths only, so `next` cannot be an open redirect. */
const isSafePath = (value: string | null): value is string =>
  !!value && value.startsWith("/") && !value.startsWith("//");

const clerk = clerkMiddleware(async (auth, request) => {
  const signIn = isSignIn(request) && !clerkOwnsSignInRoute;
  const signUp = isSignUp(request) && !clerkOwnsSignUpRoute;
  if (!signIn && !signUp) return;

  const { userId, redirectToSignIn, redirectToSignUp } = await auth();
  const next = request.nextUrl.searchParams.get(SEARCH_PARAM_KEYS.nextUrl);
  const after = signIn ? clerkConfig.afterSignInUrl : clerkConfig.afterSignUpUrl;
  const returnBackUrl = new URL(isSafePath(next) ? next : after, request.url);

  if (userId) return NextResponse.redirect(returnBackUrl);

  return signIn ? redirectToSignIn({ returnBackUrl }) : redirectToSignUp({ returnBackUrl });
});

const passThrough = () => NextResponse.next();

export default isClerkActive() ? clerk : passThrough;

export const config = {
  matcher: [
    // Skip Next internals and static files, unless found in search params
    "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    // Always run for API routes
    "/(api|trpc)(.*)",
  ],
};

import { ClerkProvider } from "@clerk/nextjs";
import type { ReactNode } from "react";
import { isClerkActive } from "@/lib/auth/auth-strategy";
import { clerkConfig, getClerkPublishableKey } from "@/lib/auth/clerk-config";

/**
 * Wraps the tree in `ClerkProvider` when Clerk is the active strategy
 * (`AUTH_STRATEGY=clerk` plus both keys); otherwise renders children as they
 * are. Mounted through `src/config/providers/clerk.provider.tsx`.
 *
 * Deliberately a server component: `ClerkProvider` from `@clerk/nextjs` reads
 * the request's auth state on the server so the first render already knows
 * who is signed in.
 */
interface ClerkProviderWrapperProps {
  children: ReactNode;
}

export function ClerkProviderWrapper({ children }: ClerkProviderWrapperProps) {
  if (!isClerkActive()) {
    return <>{children}</>;
  }

  return (
    <ClerkProvider
      publishableKey={getClerkPublishableKey()}
      appearance={clerkConfig.appearance}
      signInFallbackRedirectUrl={clerkConfig.afterSignInUrl}
      signUpFallbackRedirectUrl={clerkConfig.afterSignUpUrl}
      afterSignOutUrl={clerkConfig.afterSignOutUrl}
    >
      {children}
    </ClerkProvider>
  );
}

export default ClerkProviderWrapper;

"use client";

import { SignIn, SignOutButton, SignUp, UserButton } from "@clerk/nextjs";
import { isClerkActive } from "@/lib/auth/auth-strategy";
import { clerkConfig } from "@/lib/auth/clerk-config";

/**
 * Clerk's prebuilt auth UI, themed to match the app.
 *
 * The default flow uses Clerk's hosted Account Portal (see
 * `src/lib/auth/clerk-config.ts`), so nothing renders these by default. Drop
 * `<ClerkSignInForm />` on a page to embed the form instead; hash routing keeps
 * it working on any route without a catch-all segment.
 *
 * Every component renders nothing unless Clerk is the active strategy.
 */

/**
 * Clerk Sign In Component
 */
export function ClerkSignInForm() {
  if (!isClerkActive()) return null;

  return (
    <div className="flex items-center justify-center">
      <SignIn
        routing="hash"
        appearance={clerkConfig.appearance}
        fallbackRedirectUrl={clerkConfig.afterSignInUrl}
        signUpUrl={clerkConfig.signUpUrl}
      />
    </div>
  );
}

/**
 * Clerk Sign Up Component
 */
export function ClerkSignUpForm() {
  if (!isClerkActive()) return null;

  return (
    <div className="flex items-center justify-center">
      <SignUp
        routing="hash"
        appearance={clerkConfig.appearance}
        fallbackRedirectUrl={clerkConfig.afterSignUpUrl}
        signInUrl={clerkConfig.signInUrl}
      />
    </div>
  );
}

/**
 * Clerk User Button - Shows user profile menu when authenticated
 */
export function ClerkUserButton() {
  if (!isClerkActive()) return null;

  return (
    <UserButton
      appearance={clerkConfig.appearance}
      userProfileUrl={clerkConfig.userProfileUrl}
      afterSignOutUrl={clerkConfig.afterSignOutUrl}
    />
  );
}

/**
 * Clerk Sign Out Button
 */
interface ClerkSignOutButtonProps {
  children?: React.ReactNode;
  className?: string;
}

export function ClerkSignOutButton({ children, className }: ClerkSignOutButtonProps) {
  if (!isClerkActive()) return null;

  return (
    <SignOutButton redirectUrl={clerkConfig.afterSignOutUrl}>
      {children ?? (
        <button type="button" className={className}>
          Sign Out
        </button>
      )}
    </SignOutButton>
  );
}

/**
 * Wrapper component that conditionally renders Clerk forms based on auth strategy
 */
interface ConditionalClerkComponentProps {
  children: React.ReactNode;
  fallback?: React.ReactNode;
}

export function ConditionalClerkComponent({
  children,
  fallback = null,
}: ConditionalClerkComponentProps) {
  return <>{isClerkActive() ? children : fallback}</>;
}

import { env } from "@/env";

/**
 * Authentication Strategy Types
 */
export type AuthStrategy = "clerk" | "stack" | "authjs" | "better-auth" | "guest";

/**
 * The explicit `AUTH_STRATEGY` choice, if any.
 *
 * The client bundle only sees the `NEXT_PUBLIC_` mirror (features-config.ts
 * copies it at build time); the server can read either, and falls back to the
 * raw variable in scripts and tests where next.config never ran.
 *
 * The accepted values are the `AUTH_STRATEGY` enum in `src/env.ts`. The result
 * is widened to `AuthStrategy` so a project whose `env.ts` predates one of the
 * strategies (a Bones checkout before the `clerk` item, say) still compiles.
 */
function configuredStrategy(): AuthStrategy | undefined {
  const isServer = typeof window === "undefined";
  const configured = env.NEXT_PUBLIC_AUTH_STRATEGY ?? (isServer ? env.AUTH_STRATEGY : undefined);
  return configured as AuthStrategy | undefined;
}

/**
 * Whether any Auth.js provider is switched on.
 *
 * This has to be `.some`, not a `??` chain. These flags are optional booleans,
 * so an explicit `NEXT_PUBLIC_FEATURE_AUTH_RESEND_ENABLED=false` is non-nullish
 * and a `??` chain stops right there, reporting guest mode even when GitHub or
 * Google is switched on.
 */
function hasAuthJsProvider(): boolean {
  return [
    env.NEXT_PUBLIC_FEATURE_AUTH_RESEND_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_CREDENTIALS_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_GITHUB_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_GOOGLE_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_DISCORD_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_GITLAB_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_BITBUCKET_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_TWITTER_ENABLED,
  ].some(Boolean);
}

/**
 * Something only an Auth.js deployment would set: a session strategy override,
 * or the Payload-backed credentials provider.
 */
function hasAuthJsSignal(): boolean {
  const isServer = typeof window === "undefined";
  const sessionStrategy = isServer ? env.NEXTAUTH_SESSION_STRATEGY : undefined;
  return Boolean(sessionStrategy) || env.NEXT_PUBLIC_FEATURE_AUTH_CREDENTIALS_ENABLED === true;
}

/**
 * Determines which authentication strategy to use.
 *
 * Priority: explicit AUTH_STRATEGY > Better Auth > Auth.js > Guest
 *
 * - `AUTH_STRATEGY=clerk` picks Clerk when it is configured
 *   (NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY plus CLERK_SECRET_KEY). Clerk is a paid,
 *   hosted service, so it is never picked automatically: the keys alone do
 *   nothing until this variable says so.
 * - `AUTH_STRATEGY=better-auth` picks Better Auth when it is configured
 *   (DATABASE_URL plus BETTER_AUTH_SECRET or APP_SECRET).
 * - `AUTH_STRATEGY=authjs` keeps the Auth.js provider detection.
 * - Unset: Better Auth when it is configured and nothing Auth.js-specific is,
 *   otherwise the Auth.js detection. That makes Better Auth the default for a
 *   new project while an existing Auth.js deployment keeps working untouched.
 *
 * A strategy that is selected but not configured falls through to the
 * detection below, the same way `AUTH_STRATEGY=better-auth` without a database
 * does, so a half-configured deployment degrades to Auth.js or guest mode
 * instead of a provider that cannot start.
 */
export function getAuthStrategy(): AuthStrategy {
  const configured = configuredStrategy();
  const clerkReady = env.NEXT_PUBLIC_FEATURE_AUTH_CLERK_ENABLED === true;
  const betterAuthReady = env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED === true;

  if (configured === "clerk" && clerkReady) {
    return "clerk";
  }

  if (configured === "better-auth" && betterAuthReady) {
    return "better-auth";
  }

  if (configured === undefined && betterAuthReady && !hasAuthJsSignal()) {
    return "better-auth";
  }

  if (hasAuthJsProvider()) {
    return "authjs";
  }

  // Fall back to guest mode
  return "guest";
}

/**
 * Check if authentication is available
 */
export function isAuthenticationAvailable(): boolean {
  return getAuthStrategy() !== "guest";
}

/**
 * Check if Clerk is the active auth strategy
 */
export function isClerkActive(): boolean {
  return getAuthStrategy() === "clerk";
}

/**
 * Check if Auth.js is the active auth strategy
 */
export function isAuthJSActive(): boolean {
  return getAuthStrategy() === "authjs";
}

/**
 * Check if Better Auth is the active auth strategy
 */
export function isBetterAuthActive(): boolean {
  return getAuthStrategy() === "better-auth";
}

/**
 * Check if guest mode is active
 */
export function isGuestModeActive(): boolean {
  return getAuthStrategy() === "guest";
}

import type { Session } from "next-auth";
import { type User, UserRole } from "@/types/user";

/**
 * Better Auth session -> Auth.js `Session`, and Clerk user -> Auth.js `Session`.
 *
 * Pure and dependency-free so the server facades (`@/server/better-auth/facade`,
 * `@/server/clerk/facade`) and the client hooks (`@/lib/auth/use-session`,
 * `@/lib/auth/clerk-client`) produce the same shape, which is what every
 * component and service in the app reads.
 */

/** The subset of a Better Auth session (server `getSession` or client `useSession`) that is read. */
export interface BetterAuthSessionResult {
  session: { expiresAt: Date | string };
  user: {
    id: string;
    email: string;
    name?: string | null;
    image?: string | null;
    emailVerified?: boolean | null;
    emailVerifiedAt?: Date | string | null;
    role?: string | null;
    createdAt?: Date | string;
    updatedAt?: Date | string;
  };
}

const toDate = (value: Date | string | number | null | undefined): Date | null => {
  if (value === null || value === undefined) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

const toRole = (value: string | null | undefined): UserRole =>
  value === UserRole.admin ? UserRole.admin : UserRole.user;

/**
 * `emailVerified` prefers the Auth.js timestamp (read through the
 * `emailVerifiedAt` additional field) and falls back to the boolean flag.
 */
export function mapBetterAuthSession(result: BetterAuthSessionResult | null): Session | null {
  if (!result?.user?.id) return null;
  const { user, session } = result;
  const role = toRole(user.role);
  const emailVerified = toDate(user.emailVerifiedAt) ?? (user.emailVerified ? new Date() : null);
  const expires = toDate(session.expiresAt) ?? new Date(0);

  const mapped: User = {
    id: user.id,
    email: user.email,
    name: user.name ?? null,
    image: user.image ?? null,
    emailVerified,
    role,
    isAdmin: role === UserRole.admin,
    createdAt: toDate(user.createdAt) ?? undefined,
    updatedAt: toDate(user.updatedAt) ?? undefined,
  };

  return { user: mapped, expires: expires.toISOString() };
}

/**
 * The subset of a Clerk user that is read. Structural on purpose: the server's
 * `User` from `@clerk/nextjs/server` (timestamps as epoch milliseconds) and the
 * client's `UserResource` from `@clerk/nextjs` (timestamps as `Date`) both fit,
 * and this file never imports Clerk.
 */
export interface ClerkUserLike {
  id: string;
  primaryEmailAddress?: {
    emailAddress: string;
    verification?: { status?: string | null } | null;
  } | null;
  fullName?: string | null;
  firstName?: string | null;
  lastName?: string | null;
  imageUrl?: string | null;
  /** `role` is read from here; set it per user in the Clerk dashboard. */
  publicMetadata?: Record<string, unknown> | null;
  createdAt?: Date | number | null;
  updatedAt?: Date | number | null;
}

const clerkName = (user: ClerkUserLike): string | null => {
  if (user.fullName) return user.fullName;
  const joined = [user.firstName, user.lastName].filter(Boolean).join(" ");
  return joined || null;
};

/**
 * Clerk user -> Auth.js `Session`. `expiresAt` is the session's expiry: the
 * `exp` claim (seconds) on the server, `session.expireAt` on the client.
 * `role` comes from `publicMetadata.role` when it is `"admin"`; everything
 * else is a plain user.
 */
export function mapClerkSession(
  user: ClerkUserLike | null | undefined,
  expiresAt: Date | number | string | null | undefined
): Session | null {
  if (!user?.id) return null;
  const roleValue = user.publicMetadata?.role;
  const role = toRole(typeof roleValue === "string" ? roleValue : null);
  const primary = user.primaryEmailAddress ?? null;
  const expires =
    typeof expiresAt === "number" && expiresAt < 1e12
      ? new Date(expiresAt * 1000) // a JWT `exp` claim is in seconds
      : (toDate(expiresAt) ?? new Date(0));

  const mapped: User = {
    id: user.id,
    email: primary?.emailAddress ?? "",
    name: clerkName(user),
    image: user.imageUrl || null,
    emailVerified: primary?.verification?.status === "verified" ? new Date() : null,
    role,
    isAdmin: role === UserRole.admin,
    createdAt: toDate(user.createdAt) ?? undefined,
    updatedAt: toDate(user.updatedAt) ?? undefined,
  };

  return { user: mapped, expires: expires.toISOString() };
}

"use client";

import type { Session } from "next-auth";
import {
  signIn as nextAuthSignIn,
  signOut as nextAuthSignOut,
  useSession as useNextAuthSession,
} from "next-auth/react";
import { useCallback, useEffect, useMemo } from "react";
import { routes } from "@/config/routes";
import { isBetterAuthActive, isClerkActive } from "@/lib/auth/auth-strategy";
import { clerkSignIn, clerkSignOut, useClerkSession } from "@/lib/auth/clerk-client";
import { type BetterAuthSessionResult, mapBetterAuthSession } from "@/lib/auth/session-mapping";
import { authClient } from "@/lib/better-auth/client";

/**
 * Client-side session with the `next-auth/react` API, whichever strategy is on.
 *
 * Components import `useSession`, `signIn` and `signOut` from here instead of
 * `next-auth/react`. Under Auth.js they are the `next-auth/react` originals.
 * Under Better Auth, `useSession` reads `authClient.useSession()` and maps it
 * to `{ data: { user, expires } | null, status, update }`, and `signIn` /
 * `signOut` call the Better Auth client. Under Clerk the same three come from
 * `@/lib/auth/clerk-client`. The strategy is fixed for the life of the bundle,
 * so the choice is made once at module load.
 *
 * `SessionProvider` still comes from `next-auth/react`; it wraps the tree and
 * is harmless when Better Auth or Clerk owns the session.
 */

type NextAuthUseSession = typeof useNextAuthSession;
type NextAuthSignIn = typeof nextAuthSignIn;
type NextAuthSignOut = typeof nextAuthSignOut;

type SessionStatus = "loading" | "authenticated" | "unauthenticated";

/** `next-auth/react` declares this but does not export it. */
interface UseSessionOptions<R extends boolean> {
  required: R;
  onUnauthenticated?: () => void;
}

interface SignInOptionsLike {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
  email?: string;
  password?: string;
  [key: string]: unknown;
}

interface SignOutOptionsLike {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
}

/** Providers Better Auth's client can start itself; anything else falls back to Auth.js. */
const CREDENTIALS_PROVIDER = "credentials";
const AUTHJS_ONLY_PROVIDERS = new Set(["guest", "resend", "email", "nodemailer"]);

const currentPage = () => (typeof window === "undefined" ? routes.home : window.location.href);

const navigate = (url: string) => {
  if (typeof window !== "undefined") window.location.href = url;
};

function useBetterAuthSession<R extends boolean>(options?: UseSessionOptions<R>) {
  const { data, isPending, refetch } = authClient.useSession();
  const session = useMemo(
    () => mapBetterAuthSession(data as unknown as BetterAuthSessionResult | null),
    [data]
  );
  const status: SessionStatus = isPending
    ? "loading"
    : session
      ? "authenticated"
      : "unauthenticated";

  const update = useCallback(async (): Promise<Session | null> => {
    await refetch();
    const fresh = await authClient.getSession();
    return mapBetterAuthSession(fresh.data);
  }, [refetch]);

  const required = options?.required === true;
  const onUnauthenticated = options?.onUnauthenticated;
  useEffect(() => {
    if (!required || status !== "unauthenticated") return;
    if (onUnauthenticated) onUnauthenticated();
    else navigate(routes.auth.signIn);
  }, [required, status, onUnauthenticated]);

  return { data: session, status, update };
}

export const useSession = (
  isClerkActive()
    ? useClerkSession
    : isBetterAuthActive()
      ? useBetterAuthSession
      : useNextAuthSession
) as NextAuthUseSession;

async function betterAuthSignIn(provider: string | undefined, options?: SignInOptionsLike) {
  const callbackURL = options?.redirectTo ?? options?.callbackUrl ?? currentPage();
  const shouldRedirect = options?.redirect !== false;

  if (provider === CREDENTIALS_PROVIDER) {
    const { data, error } = await authClient.signIn.email({
      email: typeof options?.email === "string" ? options.email : "",
      password: typeof options?.password === "string" ? options.password : "",
      callbackURL,
    });
    if (!error && shouldRedirect) navigate(callbackURL);
    return {
      ok: !error,
      error: error?.message ?? error?.code,
      code: error?.code,
      status: error?.status ?? 200,
      url: data ? callbackURL : null,
    };
  }

  const { data, error } = await authClient.signIn.social({
    provider: provider ?? "github",
    callbackURL,
    disableRedirect: !shouldRedirect,
  });
  return {
    ok: !error,
    error: error?.message ?? error?.code,
    code: error?.code,
    status: error?.status ?? 200,
    url: data?.url ?? null,
  };
}

/**
 * `signIn(provider, options)` from `next-auth/react`, or the Better Auth
 * client when it is active. Social providers start the OAuth flow, and
 * `"credentials"` signs in with email and password. `redirect: false` returns
 * the `{ ok, error, url }` response instead of navigating. Auth.js-only
 * providers (`guest`, `resend`) always go through Auth.js. Under Clerk every
 * provider goes to Clerk's hosted sign-in page.
 */
export const signIn = (async (
  provider?: string,
  options?: SignInOptionsLike | FormData,
  authorizationParams?: unknown
) => {
  const opts =
    options instanceof FormData ? (Object.fromEntries(options) as SignInOptionsLike) : options;
  if (isClerkActive()) return clerkSignIn(provider, opts);
  if (!isBetterAuthActive() || (provider && AUTHJS_ONLY_PROVIDERS.has(provider))) {
    return (nextAuthSignIn as (...args: unknown[]) => Promise<unknown>)(
      provider,
      options,
      authorizationParams
    );
  }
  return betterAuthSignIn(provider, opts);
}) as NextAuthSignIn;

/**
 * `signOut(options)` from `next-auth/react`, or the Better Auth or Clerk client
 * when one is active: revokes the session, then navigates to `callbackUrl` /
 * `redirectTo` (default home) unless `redirect: false`.
 */
export const signOut = (async (options?: SignOutOptionsLike) => {
  if (isClerkActive()) return clerkSignOut(options);
  if (!isBetterAuthActive()) {
    return (nextAuthSignOut as (...args: unknown[]) => Promise<unknown>)(options);
  }
  const url = options?.redirectTo ?? options?.callbackUrl ?? routes.home;
  await authClient.signOut();
  if (options?.redirect !== false) navigate(url);
  return { url };
}) as NextAuthSignOut;

import { DrizzleAdapter } from "@auth/drizzle-adapter";
import type { NextAuthResult, Session } from "next-auth";
import NextAuth from "next-auth";
import { cache } from "react";
import { buildTimeFeatures } from "@/config/features-config";
import { routes } from "@/config/routes";
import { STATUS_CODES } from "@/config/status-codes";
import { env } from "@/env";
import { isBetterAuthActive, isClerkActive } from "@/lib/auth/auth-strategy";
import { logger } from "@/lib/logger";
import { redirect, routeRedirect } from "@/lib/utils/redirect";
import { authOptions } from "@/server/auth-js/auth.config";
import { isGuestOnlyMode } from "@/server/auth-js/auth-providers-utils";
import {
  betterAuthSignIn,
  betterAuthSignOut,
  getBetterAuthSession,
} from "@/server/better-auth/facade";
import { clerkSignIn, clerkSignOut, getClerkSession } from "@/server/clerk/facade";
import { db } from "@/server/db";
import { accounts, sessions, users, verificationTokens } from "@/server/db/schema";
import type { UserRole } from "@/types/user";

/**
 * Module augmentation for `next-auth` types. Allows us to add custom properties to the `session`
 * object and keep type safety.
 *
 * @see https://next-auth.js.org/getting-started/typescript#module-augmentation
 */

/**
 * Using database session strategy with credentials provider requires special handling:
 * 1. The credentials provider must create a user in the database
 * 2. The user must be properly linked between Payload CMS and Shipkit
 * 3. The session must be created in the database
 *
 * This is handled in:
 * - auth.providers.ts: The credentials provider's authorize function
 * - auth-service.ts: The validateCredentials and ensureUserSynchronized methods
 * - auth.config.ts: The signIn callback
 *
 * For guest users:
 * - JWT strategy is used since guest users don't persist in the database
 * - No adapter is used when in guest-only mode
 */
// Determine if we should use database adapter
const shouldUseDatabaseAdapter = env.NEXT_PUBLIC_FEATURE_DATABASE_ENABLED && db && !isGuestOnlyMode;

const {
  auth: nextAuthAuth,
  handlers,
  signIn: nextAuthSignIn,
  signOut: nextAuthSignOut,
  unstable_update: nextAuthUpdate,
} = buildTimeFeatures.AUTH_ENABLED
  ? NextAuth({
      ...authOptions,
      trustHost: true,
      secret: env.AUTH_SECRET ?? "supersecretshipkit",
      // Override session strategy based on adapter usage
      session: {
        ...authOptions.session,
        strategy: shouldUseDatabaseAdapter ? "database" : "jwt",
      },
      // Use database adapter only when not in guest-only mode and database is available
      adapter: shouldUseDatabaseAdapter
        ? DrizzleAdapter(db as any, {
            usersTable: users,
            accountsTable: accounts,
            sessionsTable: sessions,
            verificationTokensTable: verificationTokens,
          })
        : undefined,
      logger: {
        error: (code: Error, ...message: unknown[]) => {
          logger.error(code, message);
        },
        warn: (code: string, ...message: unknown[]) => {
          logger.warn(code, message);
        },
        debug: (code: string, ...message: unknown[]) => {
          logger.debug(code, message);
        },
      },
    })
  : {
      auth: () => Promise.resolve(null),
      handlers: {
        // eslint-disable-next-line @typescript-eslint/require-await -- NextAuth handler signature requires async
        GET: async (request: Request) => {
          const url = new URL(request.url);
          const path = url.pathname;
          if (path.includes("/auth/session")) {
            // Gracefully indicate no active session when auth is disabled
            return Response.json(null, { status: 200 });
          }
          return Response.json(
            {
              ok: false,
              error: "AUTH_DISABLED",
              message:
                "Authentication is not configured. Add database and/or auth provider environment variables to enable sign-in.",
              docs: "https://errors.authjs.dev#autherror",
            },
            { status: 503 }
          );
        },
        // eslint-disable-next-line @typescript-eslint/require-await -- NextAuth handler signature requires async
        POST: async () =>
          Response.json(
            {
              ok: false,
              error: "AUTH_DISABLED",
              message:
                "Authentication is not configured. Add database and/or auth provider environment variables to enable sign-in.",
              docs: "https://errors.authjs.dev#autherror",
            },
            { status: 503 }
          ),
      },
      signIn: () => Promise.resolve(),
      signOut: () => Promise.resolve(),
      unstable_update: () => Promise.resolve({} as any),
    };
/**
 * Strategy dispatch. `getAuthStrategy()` picks Clerk, Better Auth or Auth.js
 * from the environment; the exports below keep the Auth.js signatures either
 * way so the 50-odd importers of this module never see the difference. Auth.js
 * stays exactly as it was when it is the active strategy.
 */
type NextAuthSignIn = NextAuthResult["signIn"];
type NextAuthSignOut = NextAuthResult["signOut"];
type NextAuthUpdate = NextAuthResult["unstable_update"];

const signIn = (async (...args: Parameters<NextAuthSignIn>) => {
  if (isClerkActive()) return clerkSignIn(args[0], args[1]);
  if (isBetterAuthActive()) return betterAuthSignIn(args[0], args[1]);
  return (nextAuthSignIn as NextAuthSignIn)(...args);
}) as NextAuthSignIn;

const signOut = (async (...args: Parameters<NextAuthSignOut>) => {
  if (isClerkActive()) return clerkSignOut(args[0]);
  if (isBetterAuthActive()) return betterAuthSignOut(args[0]);
  return (nextAuthSignOut as NextAuthSignOut)(...args);
}) as NextAuthSignOut;

const update = (async (...args: Parameters<NextAuthUpdate>) => {
  if (isClerkActive() || isBetterAuthActive()) {
    // Clerk and Better Auth sessions are not tokens; there is nothing to refresh here.
    logger.debug("[auth] update() is a no-op under Clerk and Better Auth");
    return null;
  }
  return (nextAuthUpdate as NextAuthUpdate)(...args);
}) as NextAuthUpdate;

interface AuthProps {
  errorCode?: string;
  nextUrl?: string;
  protect?: boolean;
  redirect?: boolean;
  redirectTo?: string;
  role?: UserRole;
}
type ProtectedSession = Session & { user: NonNullable<Session["user"]> };

// Overloads and implementation for authWithOptions
function authWithOptions(props: { protect: true } & AuthProps): Promise<ProtectedSession>;
function authWithOptions(props?: AuthProps): Promise<Session | null>;
async function authWithOptions(props?: AuthProps) {
  const session = isClerkActive()
    ? await getClerkSession()
    : isBetterAuthActive()
      ? await getBetterAuthSession()
      : await nextAuthAuth();
  const { errorCode, redirect: shouldRedirect, nextUrl } = props ?? {};

  // Route protected
  // Use clear boolean logic without nullish coalescing on non-nullish expressions
  const protect =
    (props?.protect ?? false) || props?.redirectTo !== undefined || (shouldRedirect ?? false);
  // Under Clerk, src/proxy.ts forwards the sign-in route to Clerk's hosted page.
  const redirectTo = props?.redirectTo ?? routes.auth.signIn;

  const handleRedirect = (code: string) => {
    logger.warn(`[authWithOptions] Redirecting to ${redirectTo} with code ${code}`);

    // Determine if we're in a route handler context
    const isFromRouteHandler = typeof Response !== "undefined" && typeof window === "undefined";

    if (isFromRouteHandler) {
      return routeRedirect(redirectTo, {
        code,
        nextUrl,
      });
    }

    return redirect(redirectTo, {
      code,
      nextUrl,
    });
  };

  // TODO: Handle refresh token error
  // if (session?.error === "RefreshTokenError") {
  //   return handleRedirect(STATUS_CODES.AUTH_REFRESH.code);
  // }

  if (protect && !session?.user?.id) {
    return handleRedirect(errorCode ?? STATUS_CODES.AUTH.code);
  }

  // TODO: RBAC
  // if (role && session?.user?.role !== role) {
  //   return handleRedirect(errorCode ?? STATUS_CODES.AUTH_ROLE.code); // TODO: We shouldn't sign them out
  // }

  return session;
}

const cachedAuth = cache(authWithOptions);

export {
  // authWithOptions as auth,
  cachedAuth as auth,
  handlers,
  signIn,
  signOut,
  update,
};

